package com.autoops.credential.controller;import com.autoops.common.security.CurrentUser;import com.autoops.credential.service.CredentialManagementService;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/credentials")public class CredentialController{private final CredentialManagementService service;private final CurrentUser current;public CredentialController(CredentialManagementService s,CurrentUser c){service=s;current=c;}public record Create(String name,String username,String password){}@GetMapping public List<CredentialManagementService.View> list(){return service.list(current.id());}@PostMapping public CredentialManagementService.View create(@RequestBody Create r){return service.create(current.id(),r.name(),r.username(),r.password());}@DeleteMapping("/{id}")public void delete(@PathVariable Long id){service.delete(current.id(),id);}}
